const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Cincinnati location
  const cincinnati = ee.Geometry.Point([-84.5, 39.1]);

  // Use ERA5-Land hourly data for 2m temperature
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY');

  // Function to get mean February temperature for a given year
  function getFebTemp(year) {
    const startDate = ee.Date.fromYMD(year, 2, 1);
    const endDate = ee.Date.fromYMD(year, 3, 1);

    const col = era5
      .filterDate(startDate, endDate)
      .filterBounds(cincinnati)
      .select('temperature_2m');

    const size = col.size().getInfo();
    if (size === 0) {
      return null;
    }

    const meanImg = col.mean();
    const temp = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: cincinnati,
      scale: 11132,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    // Convert from Kelvin to Celsius
    return temp !== null ? temp - 273.15 : null;
  }

  // Get February 2018 temperature
  const temp2018 = getFebTemp(2018);
  if (temp2018 === null) {
    console.log("No data for February 2018");
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`Feb 2018: ${temp2018.toFixed(2)}°C`);

  // Get temperatures for 2010-2017
  const years = [2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017];
  let warmest = -Infinity;
  let allValid = true;

  for (let year of years) {
    const temp = getFebTemp(year);
    if (temp === null) {
      console.log(`No data for February ${year}`);
      allValid = false;
      continue;
    }
    console.log(`Feb ${year}: ${temp.toFixed(2)}°C`);
    if (temp > warmest) {
      warmest = temp;
    }
  }

  if (!allValid) {
    console.log("<answer>C1</answer>");
    return;
  }

  if (temp2018 === null || isNaN(temp2018) || warmest === -Infinity) {
    console.log("Calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Warmest 2010-2017: ${warmest.toFixed(2)}°C`);

  if (temp2018 > warmest) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
